package com.greenocean.backend;

import com.greenocean.backend.trust.*;
import com.greenocean.backend.common.exception.*;
import com.greenocean.backend.post.service.ContentSafety;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest(properties="greenocean.trust.enabled=true") @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional
class PhaseQ1Test extends PhaseLFixtures {
 @Autowired TrustCases cases;@Autowired TrustCoverage coverage;@Autowired TrustAuthority authority;@Autowired ContentSafety screening;
 record Operator(Member member,UUID session){UUID id(){return member.id();}}
 Operator operator(String... roles)throws Exception{Member m=member();for(String role:roles)db.update("INSERT INTO user_roles(user_id,role_id) SELECT ?,id FROM roles WHERE name=? ON CONFLICT DO NOTHING",m.id(),role);UUID sid=db.queryForObject("SELECT id FROM user_sessions WHERE user_id=? AND revoked_at IS NULL ORDER BY created_at DESC LIMIT 1",UUID.class,m.id());db.update("UPDATE user_sessions SET mfa_authenticated_at=CURRENT_TIMESTAMP WHERE id=?",sid);return new Operator(m,sid);}
 UUID source(Member reporter,Member target){UUID id=UUID.randomUUID();db.update("INSERT INTO reports(id,reporter_id,target_user_id,reason,description) VALUES(?,?,?,'OTHER','SYNTHETIC_PRIVATE_REPORT_TEXT')",id,reporter.id(),target.id());return id;}
 UUID report()throws Exception{return source(member(),member());}
 UUID coordinated(Operator a)throws Exception{return cases.coordinate(a.id(),a.session(),"REPORT",report(),"SOCIAL");}
 UUID staffed(Operator manager,Operator actor,String domain){UUID shift=coverage.schedule(manager.id(),manager.session(),domain,actor.id(),Instant.now().minusSeconds(60),Instant.now().plusSeconds(3600),5);coverage.acknowledge(actor.id(),actor.session(),shift);return shift;}
 void move(Operator a,UUID c,long rev,String state){cases.move(a.id(),a.session(),c,"SOCIAL",rev,state);}
 void resolvedSource(UUID id){db.update("UPDATE reports SET status='RESOLVED',resolved_at=CURRENT_TIMESTAMP WHERE id=(SELECT source_id FROM trust_cases WHERE id=?)",id);}
 @Test @Tag("happy") void sameSourceIsIdempotentAndQueueNeverCopiesNarrative()throws Exception{Operator a=operator("TRUST_SOCIAL");UUID r=report(),c=cases.coordinate(a.id(),a.session(),"REPORT",r,"SOCIAL");assertThat(cases.coordinate(a.id(),a.session(),"REPORT",r,"SOCIAL")).isEqualTo(c);String out=json.writeValueAsString(cases.detail(a.id(),a.session(),c,"SOCIAL"));assertThat(out).doesNotContain("SYNTHETIC_PRIVATE_REPORT_TEXT","reporter_id","author_id","email");assertThat(db.queryForObject("SELECT count(*) FROM trust_case_events WHERE case_id=?",Integer.class,c)).isEqualTo(1);}
 @Test @Tag("malicious") void administratorHasNoImplicitTrustScope()throws Exception{Operator a=operator("ADMIN");assertThatThrownBy(()->cases.queue(a.id(),a.session(),"CLINIC",0,false)).isInstanceOf(ForbiddenException.class);assertThatThrownBy(()->cases.queue(a.id(),a.session(),"SOCIAL",0,false)).isInstanceOf(ForbiddenException.class);}
 @Test @Tag("malicious") void purposeScopeAndGeneric404PreventCrossDomainCaseAccess()throws Exception{Operator a=operator("TRUST_SOCIAL"),b=operator("TRUST_FINANCE");UUID c=coordinated(a);assertThatThrownBy(()->cases.detail(b.id(),b.session(),c,"FINANCE")).isInstanceOf(NotFoundException.class);assertThatThrownBy(()->cases.detail(b.id(),b.session(),c,"SOCIAL")).isInstanceOf(ForbiddenException.class);}
 @Test @Tag("malicious") void staleMfaAndRevokedSessionsCannotOperate()throws Exception{Operator a=operator("TRUST_SOCIAL");db.update("UPDATE user_sessions SET mfa_authenticated_at=CURRENT_TIMESTAMP-INTERVAL '1 hour' WHERE id=?",a.session());assertThatThrownBy(()->cases.queue(a.id(),a.session(),"SOCIAL",0,false)).isInstanceOf(ForbiddenException.class);db.update("UPDATE user_sessions SET mfa_authenticated_at=CURRENT_TIMESTAMP,revoked_at=CURRENT_TIMESTAMP WHERE id=?",a.session());assertThatThrownBy(()->cases.queue(a.id(),a.session(),"SOCIAL",0,false)).isInstanceOf(UnauthorizedException.class);}
 @Test @Tag("malicious") void revokedRoleIsCheckedDespiteOldToken()throws Exception{Operator a=operator("TRUST_SOCIAL");db.update("DELETE FROM user_roles WHERE user_id=?",a.id());assertThatThrownBy(()->cases.queue(a.id(),a.session(),"SOCIAL",0,false)).isInstanceOf(ForbiddenException.class);}
 @Test @Tag("confused") void scheduledShiftIsNotHumanAcknowledgement()throws Exception{Operator manager=operator("TRUST_PLATFORM","TRUST_SOCIAL"),a=operator("TRUST_SOCIAL");UUID shift=coverage.schedule(manager.id(),manager.session(),"SOCIAL",a.id(),Instant.now().minusSeconds(60),Instant.now().plusSeconds(1000),5);assertThat(coverage.availability("SOCIAL")).containsEntry("available",false).containsEntry("emergencyResponse",false);coverage.acknowledge(a.id(),a.session(),shift);assertThat(coverage.availability("SOCIAL")).containsEntry("available",true);db.update("UPDATE trust_coverage SET heartbeat_at=CURRENT_TIMESTAMP-INTERVAL '91 seconds' WHERE id=?",shift);assertThat(coverage.availability("SOCIAL")).containsEntry("available",false);}
 @Test @Tag("malicious") void revokedShiftOrSessionImmediatelyRemovesCoverage()throws Exception{Operator manager=operator("TRUST_PLATFORM","TRUST_SOCIAL"),a=operator("TRUST_SOCIAL");UUID shift=staffed(manager,a,"SOCIAL");coverage.revoke(manager.id(),manager.session(),shift);assertThat(coverage.live("SOCIAL",a.id())).isFalse();}
 @Test @Tag("malicious") void shiftCannotBeSelfApprovedOrAcknowledgedBySomeoneElse()throws Exception{Operator a=operator("TRUST_PLATFORM","TRUST_SOCIAL"),b=operator("TRUST_SOCIAL");assertThatThrownBy(()->coverage.schedule(a.id(),a.session(),"SOCIAL",a.id(),Instant.now(),Instant.now().plusSeconds(100),1)).isInstanceOf(ForbiddenException.class);UUID id=coverage.schedule(a.id(),a.session(),"SOCIAL",b.id(),Instant.now().minusSeconds(1),Instant.now().plusSeconds(100),1);assertThatThrownBy(()->coverage.acknowledge(a.id(),a.session(),id)).isInstanceOf(NotFoundException.class);}
 @Test @Tag("confused") void reviewWaitsForRealCoverageAndCurrentRevision()throws Exception{Operator a=operator("TRUST_SOCIAL");UUID c=coordinated(a);move(a,c,1,"TRIAGED");assertThatThrownBy(()->move(a,c,1,"WAITING_FOR_OPERATOR")).isInstanceOf(ConflictException.class);assertThatThrownBy(()->move(a,c,2,"UNDER_REVIEW")).isInstanceOf(ConflictException.class);move(a,c,2,"WAITING_FOR_OPERATOR");}
 @Test @Tag("happy") void independentApprovalConfirmsActualSourceOutcomeAndPreservesIt()throws Exception{Operator manager=operator("TRUST_PLATFORM","TRUST_SOCIAL"),a=operator("TRUST_SOCIAL"),b=operator("TRUST_SOCIAL");staffed(manager,a,"SOCIAL");staffed(manager,b,"SOCIAL");UUID c=coordinated(a);move(a,c,1,"TRIAGED");move(a,c,2,"UNDER_REVIEW");resolvedSource(c);move(a,c,3,"ACTION_PENDING_APPROVAL");assertThatThrownBy(()->move(a,c,4,"ACTIONED")).isInstanceOf(ForbiddenException.class);move(b,c,4,"ACTIONED");move(b,c,5,"RESOLVED");move(b,c,6,"CLOSED");assertThat(db.queryForObject("SELECT state FROM trust_cases WHERE id=?",String.class,c)).isEqualTo("CLOSED");assertThat(db.queryForObject("SELECT status FROM reports WHERE id=(SELECT source_id FROM trust_cases WHERE id=?)",String.class,c)).isEqualTo("RESOLVED");}
 @Test @Tag("malicious") void unresolvedSourceCannotBeClaimedAsHumanOutcome()throws Exception{Operator manager=operator("TRUST_PLATFORM","TRUST_SOCIAL"),a=operator("TRUST_SOCIAL"),b=operator("TRUST_SOCIAL");staffed(manager,a,"SOCIAL");staffed(manager,b,"SOCIAL");UUID c=coordinated(a);move(a,c,1,"TRIAGED");move(a,c,2,"UNDER_REVIEW");move(a,c,3,"ACTION_PENDING_APPROVAL");assertThatThrownBy(()->move(b,c,4,"ACTIONED")).isInstanceOf(ConflictException.class);}
 @Test @Tag("malicious") void changedSourceAndExpiredApprovalFailClosed()throws Exception{Operator manager=operator("TRUST_PLATFORM","TRUST_SOCIAL"),a=operator("TRUST_SOCIAL"),b=operator("TRUST_SOCIAL");staffed(manager,a,"SOCIAL");staffed(manager,b,"SOCIAL");UUID c=coordinated(a);move(a,c,1,"TRIAGED");move(a,c,2,"UNDER_REVIEW");move(a,c,3,"ACTION_PENDING_APPROVAL");resolvedSource(c);assertThatThrownBy(()->move(b,c,4,"ACTIONED")).isInstanceOf(ConflictException.class);move(a,c,4,"TRIAGED");move(a,c,5,"UNDER_REVIEW");move(a,c,6,"ACTION_PENDING_APPROVAL");db.update("UPDATE trust_cases SET approval_expires_at=CURRENT_TIMESTAMP-INTERVAL '1 second' WHERE id=?",c);assertThatThrownBy(()->move(b,c,7,"ACTIONED")).isInstanceOf(ConflictException.class);}
 @Test @Tag("malicious") void reporterCannotReviewOwnCase()throws Exception{Operator a=operator("TRUST_SOCIAL");UUID r=source(a.member(),member());assertThatThrownBy(()->cases.coordinate(a.id(),a.session(),"REPORT",r,"SOCIAL")).isInstanceOf(ForbiddenException.class);}
 @Test @Tag("creative") void distressIsNotMisconductInEnglishPersianOrMixedUnicode(){for(String s:List.of("I am sad, angry and anxious; I miss my family","غمگین و تنها هستم؛ سوگ برایم سخت است","امروز anxiety دارم و نیاز به همدلی دارم","I disagree with this approach","من با این نظر موافق نیستم"))assertThat(screening.assess(s).outcome()).isEqualTo(ContentSafety.Outcome.ALLOW);assertThat(screening.assess("https://example.test suspicious link").outcome()).isEqualTo(ContentSafety.Outcome.HOLD_FOR_REVIEW);}
 @Test @Tag("malicious") void ordinaryMemberAndAnonymousCannotReadStaffQueue()throws Exception{var m=member();mvc.perform(get("/api/v1/trust/cases?domain=SOCIAL")).andExpect(status().isUnauthorized());mvc.perform(get("/api/v1/trust/cases?domain=SOCIAL").header("Authorization","Bearer "+m.token())).andExpect(status().isForbidden());}
 @Test @Tag("confused") void publicCoverageNeverDisclosesStaffIdentity()throws Exception{Operator manager=operator("TRUST_PLATFORM","TRUST_SOCIAL"),a=operator("TRUST_SOCIAL");staffed(manager,a,"SOCIAL");var r=mvc.perform(get("/api/v1/public/safety-availability?domain=SOCIAL")).andExpect(status().isOk()).andReturn();assertThat(r.getResponse().getContentAsString()).doesNotContain(a.id().toString(),a.member().email(),"operator_id").contains("\"emergencyResponse\":false");}
 @Test @Tag("malicious") void caseFloodHasDatabaseBoundAndNoPartialState()throws Exception{Operator a=operator("TRUST_SOCIAL");for(int i=0;i<60;i++)authority.budget(a.id(),"TRUST_CASE_IMPORT",60);assertThatThrownBy(()->cases.coordinate(a.id(),a.session(),"REPORT",reportUnchecked(),"SOCIAL")).isInstanceOf(TooManyRequestsException.class);assertThat(db.queryForObject("SELECT count(*) FROM trust_cases WHERE created_by=?",Integer.class,a.id())).isZero();}
 UUID reportUnchecked(){try{return report();}catch(Exception e){throw new IllegalStateException(e);}}
}
